:root {
  --bg: #1e1b2e;
  --bg-accent: #2a2540;
  --card: #fdfcff;
  --text: #1e1b2e;
  --muted: #5c5776;
  --primary: #6c5ce7;
  --primary-dark: #5546c9;
  --focus: #ffb703;
  --border: #dcd8ec;
  --shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: radial-gradient(circle at 20% 10%, var(--bg-accent), var(--bg) 60%);
}

.app {
  width: 100%;
  max-width: 720px;
  background: var(--card);
  border-radius: 20px;
  padding: 28px 24px 20px;
  box-shadow: var(--shadow);
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 1rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 10px;
  margin-bottom: 24px;
}

.swatch {
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #fff;
  min-width: 0;
}

.swatch-color {
  height: 96px;
  width: 100%;
  transition: filter 0.15s ease;
}

.swatch-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 4px 10px;
}

.hex {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
  word-break: break-all;
  text-align: center;
}

.lock {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  border: 1px solid var(--border);
  background: #fff;
  color: var(--muted);
  border-radius: 999px;
  padding: 4px 8px;
  font-size: 0.75rem;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
}

.lock:hover {
  background: #f1eefc;
  color: var(--primary-dark);
}

.lock:active {
  transform: scale(0.96);
}

.lock[aria-pressed="true"] {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.lock-icon {
  font-size: 0.85rem;
  line-height: 1;
}

.controls {
  display: flex;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 999px;
  padding: 12px 28px;
  cursor: pointer;
  border: 2px solid transparent;
  transition: background 0.15s ease, transform 0.05s ease, box-shadow 0.15s ease;
}

.btn.primary {
  background: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: var(--primary-dark);
}

.btn.primary:active {
  transform: scale(0.98);
}

.btn:focus-visible,
.lock:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.footer {
  margin-top: 20px;
  text-align: center;
  color: var(--muted);
  font-size: 0.875rem;
}

.footer p {
  margin: 0;
}

@media (max-width: 520px) {
  .app {
    padding: 22px 16px 16px;
  }

  .palette {
    gap: 6px;
  }

  .swatch-color {
    height: 72px;
  }

  .hex {
    font-size: 0.7rem;
  }

  .lock {
    padding: 3px 6px;
    font-size: 0.7rem;
  }

  .lock-label {
    display: none;
  }
}

(function () {
  "use strict";

  const paletteEl = document.getElementById("palette");
  const generateBtn = document.getElementById("generate");

  const state = {
    colors: [],
    locked: [false, false, false, false, false],
  };

  const SCHEMES = ["analogous", "complementary", "triadic", "split"];

  function randomInt(max) {
    return Math.floor(Math.random() * max);
  }

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const k = (n) => (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const color = l - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
      return Math.round(255 * color)
        .toString(16)
        .padStart(2, "0");
    };
    return `#${f(0)}${f(8)}${f(4)}`.toUpperCase();
  }

  function generateHarmoniousPalette() {
    const baseHue = randomInt(360);
    const scheme = SCHEMES[randomInt(SCHEMES.length)];
    const baseSat = 55 + randomInt(25);
    const baseLight = 45 + randomInt(15);

    const hueOffsets = {
      analogous: [0, 20, 40, 60, 80],
      complementary: [0, 0, 180, 180, 30],
      triadic: [0, 120, 240, 60, 300],
      split: [0, 150, 210, 30, 330],
    };

    const offsets = hueOffsets[scheme];
    return offsets.map((offset, i) => {
      const hue = (baseHue + offset) % 360;
      const sat = Math.min(95, baseSat + (i % 2 === 0 ? 0 : 10));
      const light = Math.min(80, Math.max(25, baseLight + (i - 2) * 6));
      return hslToHex(hue, sat, light);
    });
  }

  function render() {
    paletteEl.innerHTML = "";
    state.colors.forEach((hex, index) => {
      const swatch = document.createElement("div");
      swatch.className = "swatch";

      const colorBlock = document.createElement("div");
      colorBlock.className = "swatch-color";
      colorBlock.style.backgroundColor = hex;
      colorBlock.setAttribute("aria-hidden", "true");

      const info = document.createElement("div");
      info.className = "swatch-info";

      const hexLabel = document.createElement("span");
      hexLabel.className = "hex";
      hexLabel.textContent = hex;

      const lockBtn = document.createElement("button");
      lockBtn.type = "button";
      lockBtn.className = "lock";
      lockBtn.setAttribute("aria-pressed", String(state.locked[index]));
      lockBtn.setAttribute(
        "aria-label",
        `${state.locked[index] ? "Unlock" : "Lock"} color ${hex}`
      );

      const icon = document.createElement("span");
      icon.className = "lock-icon";
      icon.textContent = state.locked[index] ? "\u{1F512}" : "\u{1F513}";
      icon.setAttribute("aria-hidden", "true");

      const label = document.createElement("span");
      label.className = "lock-label";
      label.textContent = state.locked[index] ? "Locked" : "Lock";

      lockBtn.appendChild(icon);
      lockBtn.appendChild(label);

      lockBtn.addEventListener("click", () => {
        state.locked[index] = !state.locked[index];
        render();
      });

      info.appendChild(hexLabel);
      info.appendChild(lockBtn);

      swatch.appendChild(colorBlock);
      swatch.appendChild(info);
      paletteEl.appendChild(swatch);
    });
  }

  function generate() {
    const fresh = generateHarmoniousPalette();
    state.colors = fresh.map((hex, i) =>
      state.locked[i] ? state.colors[i] : hex
    );
    render();
  }

  generateBtn.addEventListener("click", generate);

  // Initial palette
  state.colors = generateHarmoniousPalette();
  render();
})();
